require "pathname"

module ActiveAdminTheme
  # Gives a host's Tailwind entry file the theme CSS from the installed gem.
  # A Tailwind @import cannot compute the gem's path, and that path differs
  # between machines (a laptop, a Docker image, CI). So the path goes into a
  # generated file the host does not commit, and the entry file, which is
  # committed, imports that file by a fixed relative name.
  module CssImport
    GENERATED = "active_admin_theme.generated.css".freeze
    BEGIN_MARKER = "/* active_admin_theme:begin */".freeze
    END_MARKER = "/* active_admin_theme:end */".freeze
    BLOCK = /#{Regexp.escape(BEGIN_MARKER)}.*?#{Regexp.escape(END_MARKER)}\n?/m
    ENTRY_BLOCK = "#{BEGIN_MARKER}\n@import \"./#{GENERATED}\";\n#{END_MARKER}\n".freeze

    class << self
      def gem_css_path
        Pathname.new(File.expand_path("../../app/tailwind/active_admin_theme.css", __dir__))
      end

      def generated_path(entry)
        Pathname.new(entry).expand_path.dirname.join(GENERATED)
      end

      def generated_content(entry, css: gem_css_path)
        relative = css.relative_path_from(Pathname.new(entry).expand_path.dirname)
        "/* Generated by `rake active_admin_theme:css`. Machine-specific: do not commit. */\n@import \"#{relative}\";\n"
      end

      # Writes the generated file, and adds the fixed import to the entry file
      # if it is not there. Returns what changed, as an array of
      # [:generated | :entry, :created | :updated].
      def write(entry, css: gem_css_path)
        path = Pathname.new(entry)
        raise ArgumentError, "#{entry} does not exist" unless path.file?

        changes = []
        generated = generated_path(path)
        content = generated_content(path, css: css)
        unless generated.file? && generated.read == content
          changes << [:generated, generated.file? ? :updated : :created]
          generated.write(content)
        end

        source = path.read
        unless source.include?(ENTRY_BLOCK)
          updated = if source.match?(BLOCK)
            source.sub(BLOCK) { ENTRY_BLOCK }
          else
            (source.end_with?("\n") ? source + "\n" : source + "\n\n") + ENTRY_BLOCK
          end
          path.write(updated)
          changes << [:entry, source.match?(BLOCK) ? :updated : :created]
        end
        changes
      end
    end
  end
end
